// Every generated tool sends its one action with exactly the encoded parameters and returns a result its
// output schema accepts.
func TestGeneratedTools(t *testing.T) {
	for _, c := range generatedCases {
		t.Run(c.tool, func(t *testing.T) {
			f := &fakeAWS{answer: func(r sent, _ int) reply {
				if c.readback != "" && r.method == "GET" {
					return reply{status: 200, body: c.readback}
				}
				switch r.action {
				case c.action:
					return reply{status: 200, header: c.answerHeader, body: c.answer}
				case "GetCallerIdentity":
					return ok(identityXML)
				}
				return reply{status: 500}
			}}
			// A write is offered by name here: the effect defaults of a connection offer reads only.
			var tools []string
			if c.listed || c.confirm {
				tools = []string{c.tool}
			}
			e := newToolsEnv(t, f, baseValues(), tools)
			text, err := e.invokeConfirmed(c.tool, c.arguments, c.confirm)
			if err != nil {
				t.Fatalf("invoke: %v", err)
			}
			got := decodeResult(t, text)
			for _, key := range c.result {
				if _, ok := got[key]; !ok {
					t.Errorf("result lacks %s: %v", key, got)
				}
			}
			var call *sent
			for i := range f.requests {
				// A tool may read before or after its change: the call is the one of the tool's own method.
				if f.requests[i].action == c.action && (c.method == "" || f.requests[i].method == c.method) {
					call = &f.requests[i]
				}
			}
			if call == nil {
				t.Fatalf("requests = %v, want %s", f.actions(), c.action)
			}
			if c.method != "" {
				// The body of the test names the all-zero token of the encoder; the tool sent a random one and returned it.
				wantBody := c.body
				if c.token {
					token, _ := got["client_token"].(string)
					if token == "" || !strings.Contains(call.body, token) {
						t.Errorf("client_token = %v, not the token sent", got["client_token"])
					}
					wantBody = strings.ReplaceAll(c.body, "00000000-0000-4000-8000-000000000000", token)
				}
				if call.method != c.method || call.path != c.path || call.rawQuery != c.rawQuery || call.body != wantBody {
					t.Errorf("request = %s %s?%s %s, want %s %s?%s %s", call.method, call.path, call.rawQuery, call.body,
						c.method, c.path, c.rawQuery, wantBody)
				}
				if c.bucket != "" && call.host != c.bucket+".s3."+testRegion+".amazonaws.com" {
					t.Errorf("host = %s, want the bucket as its first label", call.host)
				}
				// The expected owner is the account of the connection, whatever an argument says.
				if got := call.header.Get("X-Amz-Expected-Bucket-Owner"); got != c.owner {
					t.Errorf("expected bucket owner = %q, want %q", got, c.owner)
				}
				return
			}
			want := len(c.form) + 2
			if c.token {
				want++
				if token, _ := got["client_token"].(string); token == "" || !formHolds(call.form, token) {
					t.Errorf("client_token = %v, not the token sent", got["client_token"])
				}
			}
			if len(call.form) != want {
				t.Errorf("form = %v, want exactly %v plus Action and Version", call.form, c.form)
			}
			for k, v := range c.form {
				if call.form.Get(k) != v {
					t.Errorf("form %s = %q, want %q", k, call.form.Get(k), v)
				}
			}
		})
	}
}

// No generated tool sends an operation its table excludes.
func TestGeneratedExclusionsAreNoTools(t *testing.T) {
	excluded := map[string][]string{
		"sts":     excludedSTSActions,
		"iam":     excludedIAMActions,
		"ses":     excludedSESActions,
		"s3":      excludedS3Actions,
		"route53": excludedROUTE53Actions,
	}
	for _, s := range generatedSpecs {
		// A restJson1 tool sends no action; its op is the operation name in words.
		name := s.action
		if s.rest != nil {
			name = strings.ReplaceAll(s.op, " ", "")
		}
		for _, action := range excluded[string(s.service)] {
			if strings.EqualFold(name, action) {
				t.Errorf("%s sends the excluded operation %s", s.descriptor.ID, action)
			}
		}
	}
}
